customGraphs.schema:
{
	"@graph": [
		{
			"@type": "WebApplication",
			"name": "GUESTPIX Free QR Code Generator",
			"url": "https://guestpix.com/qr-code-generator/",
			"description": "Free QR code generator for weddings and events. Create a custom QR code in seconds, choose your colours, and download print-ready PNG or SVG files. No sign-up required, no watermark on SVG, and codes never expire.",
			"applicationCategory": "UtilityApplication",
			"operatingSystem": "Any (web-based)",
			"offers": {
				"@type": "Offer",
				"price": "0",
				"priceCurrency": "USD"
			},
			"provider": {
				"@type": "Organization",
				"name": "GUESTPIX",
				"url": "https://guestpix.com"
			}
		},
		{
			"@type": "FAQPage",
			"mainEntity": [
				{
					"@type": "Question",
					"name": "Is this QR code generator really free?",
					"acceptedAnswer": {
						"@type": "Answer",
						"text": "Yes, it is a completely free service with no strings attached. We simply recommend testing your QR code first to ensure it points to the right location."
					}
				},
				{
					"@type": "Question",
					"name": "Do the QR codes expire?",
					"acceptedAnswer": {
						"@type": "Answer",
						"text": "No. These are static QR codes that encode your link directly, so they work forever. Many other free generators create dynamic codes that stop working when a trial ends."
					}
				},
				{
					"@type": "Question",
					"name": "Can I use a QR code to collect wedding photos from guests?",
					"acceptedAnswer": {
						"@type": "Answer",
						"text": "Yes. Point your QR code at a GUESTPIX gallery and guests can upload their photos and videos instantly, with no app required. GUESTPIX has powered photo sharing at more than 200,000 events worldwide."
					}
				},
				{
					"@type": "Question",
					"name": "Do you offer a free photo sharing plan?",
					"acceptedAnswer": {
						"@type": "Answer",
						"text": "Yes. Your free GUESTPIX event includes a unique QR code and link, up to 50 photos, digital invitations and RSVP, unlimited guests, social reactions and comments, and a zip download of all your photos. Your gallery is open for uploads immediately."
					}
				},
				{
					"@type": "Question",
					"name": "How long does my free gallery last?",
					"acceptedAnswer": {
						"@type": "Answer",
						"text": "Your gallery is open for uploads immediately and stays active for uploads and viewing for 30 days after your event date. The gallery is permanently deleted after 90 days, and you can upgrade or extend it at any time."
					}
				},
				{
					"@type": "Question",
					"name": "Can I upgrade later if I want more features?",
					"acceptedAnswer": {
						"@type": "Answer",
						"text": "Yes, and it is instant. Upgrading removes the photo limit immediately and unlocks video uploads, gallery customisation, albums, and more. Your existing photos and event details stay exactly as they are."
					}
				},
				{
					"@type": "Question",
					"name": "What's not included in the free plan?",
					"acceptedAnswer": {
						"@type": "Answer",
						"text": "Video uploads, gallery customisation such as themes and colours, albums, and a welcome video are available on paid plans."
					}
				},
				{
					"@type": "Question",
					"name": "How do I download my photos?",
					"acceptedAnswer": {
						"@type": "Answer",
						"text": "You can download your entire gallery as a ZIP file, including full-resolution photos organised by guest name and a CSV of guestbook messages. Log in at my.guestpix.com, go to the Export section, click Generate ZIP, and you will receive an email with your download link."
					}
				}
			]
		}
	]
}
